{
  "name": "opencode-tps-meter",
  "version": "0.4.2",
  "description": "Live tokens-per-second meter for OpenCode (v1 and v2)",
  "type": "module",
  "main": "./dist/index.js",
  "module": "./dist/index.mjs",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "import": {
        "types": "./dist/index.d.ts",
        "default": "./dist/index.mjs"
      },
      "require": {
        "types": "./dist/index.d.ts",
        "default": "./dist/index.js"
      }
    },
    "./server": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.mjs"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.mjs"
    },
    "./v2": {
      "types": "./dist/v2/server.d.ts",
      "import": "./dist/v2/server.mjs"
    },
    "./v2/tui": {
      "types": "./dist/v2/tui.d.ts",
      "import": "./dist/v2/tui.mjs"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "bun run build.ts",
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "bun run build",
    "typecheck:bench": "tsc -p bench/tsconfig.json",
    "bench": "bun bench/hotpath.ts && bun bench/publish.ts && bun bench/profile.ts && bun bench/memory.ts && bun bench/v1path.ts"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/ChiR24/opencode-tps-meter.git"
  },
  "homepage": "https://github.com/ChiR24/opencode-tps-meter#readme",
  "bugs": "https://github.com/ChiR24/opencode-tps-meter/issues",
  "devDependencies": {
    "@opencode-ai/plugin": "^1.15.13",
    "@opentui/core": "^0.3.0",
    "@opentui/solid": "^0.3.0",
    "solid-js": "1.9.12",
    "typescript": "^5.0.0",
    "@types/node": "^20.0.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.15.13",
    "@opentui/solid": "*",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode2",
    "ai",
    "tokens"
  ],
  "license": "MIT"
}
